const se = Application('System Events');
const out = [];
for (const name of ['Safari', 'Google Chrome', 'Zen', 'Zen Browser']) {
  if (!se.processes.whose({name: name}).length) continue;
  const proc = se.processes.byName(name);
  if (!proc.windows.length) continue;
  const queue = [proc.windows[0]];
  let seen = 0;
  while (queue.length && seen < 1500) {
    const el = queue.shift(); seen += 1;
    let role = '';
    try { role = el.role(); } catch (e) { continue; }
    if (role === 'AXWebArea') {
      try { out.push(name + ' url=' + el.attributes.byName('AXURL').value()); } catch (e) {}
      continue;
    }
    if (role === 'AXTextField' || role === 'AXComboBox') {
      try {
        const label = [el.description(), el.name(), el.title()].join(' ');
        const value = el.value();
        if (value && /address|search|url|smart/i.test(label)) out.push(name + ' address=' + value);
      } catch (e) {}
    }
    try { for (const child of el.uiElements()) queue.push(child); } catch (e) {}
  }
}
out.join(' | ').toLowerCase();

